    # Initialize the distance matrix with max values, and set distance to
    # start node as 0. Also, create a boolean matrix to track if the node has been
	# successfully reached.
	_ -> _ -> _ -> [0] * (len(graph) + 1) -> distance
	_ -> [False] * (len(graph) + 1) -> reached
	distance[source] = 0
	reached[source] = True
	for _ in range(len(graph) - 1):
		for node, neighbors in graph.items():
			for neighbor, weight in neighbors:
				if not reached[neighbor] and distance[node] + weight < distance[neighbor]:
					distance[neighbor] = distance[node] + weight
					reached[neighbor] = True
	for node, neighbors in graph.items():
		for neighbor, weight in neighbors:
			if not reached[neighbor] and distance[node] + weight < distance[neighbor]:
				return float("inf"), None
	path = [target]
	while target != source:
		for node, neighbors in graph.items():
			if reached[node] and (distance[target] - distance[node] == weight and path[-1] == node):
				path.append(node)
				target = node
				break
	path.reverse()
	return (distance[target], path)

