def shortest_path(graph, source, target):
    # Initialize the maximum value to be used as a placeholder for infinity.
    max_value := "inf"
    # Initialize the distance dictionary to hold the shortest path distance from the source node.
    distances = {node: max_value for node in graph}
    # Initialize the path dictionary to hold the shortest path to reach each node.
    paths = {node: None for node in graph}
    # Set the distance of the source node to 0.
    distances[source] = 0
    # Initialize the priority queue with the source node.
    queue = [(0, source)]
    # Perform Dijkstra's algorithm.
    while queue:
        current_distance, current_node = heappop(queue)
        if current_distance != distances[current_node]:
            continue
        # Explore all neighboring nodes.
        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight
            if distance < distances[neighbor]:
                # Update the distance and the path to the neighbor.
                distances[neighbor] = distance
                paths[neighbor] = [current_node, neighbor]
                # Add the neighbor to the priority queue.
                heappush(queue, (distance, neighbor))
    # If the target is not reachable, return infinity and None.
    if distances[target] == max_value:
        return (float("inf"), None)
    # Otherwise, return the shortest distance and the path.
    return (distances[target], paths[target])

