def shortest_path(graph, source, target, max_steps=100):
    import heapq

    def dijkstra(graph, source, target, max_steps):
        queue = [(0, source, [source])]
        visited = set()
        while queue and len(visited) < max_steps:
            dist, node, path = heapq.heappop(queue)
            if node == target:
                return (dist, path)
            if node in visited:
                continue
            visited.add(node)
            for neighbor, weight in graph.get(node, []):
                total_dist = dist + weight
                new_path = path + [neighbor]
                if neighbor not in visited and total_dist < max_steps:
                    heapq.heappush(queue, (total_dist, neighbor, new_path))
        return (float('inf'), None)
    return dijkstra(graph, source, target)
