    visited = set() # To keep track of visited nodes to avoid cycles.
    path = None # We will update this to the shortest path when found.

    # Priority queue to manage the next node to visit based on the shortest distance to it.
    from heapq import heappush, heappop
    pq = [(0, source)] # Priority Queue initialization with (distance, node)

    while pq:
        current_distance, current_node = heappop(pq)
        if current_node in visited:
            continue
        visited.add(current_node)

        # If we reached the target node, we can stop the search.
        if current_node == target:
            break

        # Explore all neighbors and update their distances if a shorter path is found.
        for neighbor, weight in graph[current_node]:
            new_distance = current_distance + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                heappush(pq, (new_distance, neighbor))

    # If we reached the target, reconstruct the path.
    if target in visited:
        path = [target]
        current_node = target
        while current_node != source:
            for neighbor, weight in graph[current_node]:
                if distances[neighbor] == distances[current_node] - weight:
                    path.append(neighbor)
                    current_node = neighbor
                    break
        path.reverse() # Reverse the list to get the correct order.

    # If the target is not reachable, return inf and None.
    return (distances[target], path) if target in distances else (float("inf"), None)

